// Build prompt dengan knowledge base context
const topic = $json.body.topic;
const audience = $json.body.audience || 'millennial';
const slideCount = $json.body.slideCount || 7;
const tone = $json.body.tone || 'casual';

// Vercel API URL untuk knowledge base
const vercelApiUrl = 'https://custom-ai-two.vercel.app/api/knowledge';
const githubBaseUrl = 'https://raw.githubusercontent.com/lumakaraid/custom-ai/main/knowledge-base/';

// Knowledge base files reference
const knowledgeFiles = [
  '01_LUMAKARA_BRAND_CHARACTER.md',
  '02_LUMAKARA_SERVICES.md',
  '03_CONTENT_TOPICS_LIBRARY.md',
  '04_INDONESIAN_CALENDAR_2026.md',
  '05_CONTENT_STRATEGY.md',
  '06_TARGET_AUDIENCE_GEN_Z.md',
  '07_TARGET_AUDIENCE_MILLENNIAL.md',
  '08_TARGET_AUDIENCE_GEN_X.md',
  '09_VISUAL_PROMPT_GUIDE.md',
  '10_BRAND_VOICE_EXAMPLES.md',
  '11_CONTENT_STRUCTURE_GUIDE.md',
  '12_CHARACTER_COUNT_RULES.md',
  '13_PHP_OUTPUT_FORMAT.md',
  '14_IMPORT_INSTRUCTIONS.md',
  '15_QUALITY_CHECKLIST.md'
];

// Build knowledge base reference
const knowledgeBase = `
Knowledge Base (Vercel API: ${vercelApiUrl}):
${knowledgeFiles.map(f => `- ${f}: ${githubBaseUrl}${f}`).join('\n')}

Semua guidelines ada di URLs di atas. Baca dan ikuti dengan teliti.
`;

const systemPrompt = `Kamu adalah Lumakara Content Creator AI.

Baca dan ikuti SEMUA guidelines dari knowledge base di GitHub:
${knowledgeBase}

Generate konten carousel Instagram untuk Lumakara dalam format PHP array sesuai 13_PHP_OUTPUT_FORMAT.md.

PASTIKAN:
✅ Brand voice konsisten (01_LUMAKARA_BRAND_CHARACTER.md)
✅ Sesuai target audience yang diminta
✅ Character count rules (12_CHARACTER_COUNT_RULES.md)
✅ Include visual prompts detail (09_VISUAL_PROMPT_GUIDE.md)
✅ PHP syntax 100% correct
✅ Follow content structure (11_CONTENT_STRUCTURE_GUIDE.md)
✅ Quality checklist passed (15_QUALITY_CHECKLIST.md)

OUTPUT FORMAT:
PHP array dengan struktur lengkap sesuai 13_PHP_OUTPUT_FORMAT.md.
Jangan lupa visual_prompt untuk setiap slide!`;

const userPrompt = `Buatkan konten carousel Instagram tentang "${topic}" untuk target audience ${audience}, ${slideCount} slide.

Tone: ${tone}

Output dalam format PHP array yang bisa langsung di-import ke WordPress.

Pastikan:
- Sesuai brand voice Lumakara
- Relevan untuk ${audience}
- ${slideCount} slide lengkap
- Visual prompt untuk setiap slide
- Character count sesuai rules
- PHP syntax correct`;

return {
  json: {
    systemPrompt,
    userPrompt,
    topic,
    audience,
    slideCount,
    tone,
    vercelApiUrl,
    githubBaseUrl
  }
};

// Extract content
const content = $json.choices[0].message.content;

// Generate filename
const date = new Date().toISOString().split('T')[0];
const topic = $('Prepare Prompt').item.json.topic.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '');
const filename = `${date}-${topic}.php`;

return {
  json: {
    success: true,
    filename,
    content,
    topic: $('Prepare Prompt').item.json.topic,
    audience: $('Prepare Prompt').item.json.audience,
    slideCount: $('Prepare Prompt').item.json.slideCount,
    generatedAt: new Date().toISOString()
  }
};
